using Microsoft.ML;
using Microsoft.ML.Data;
using ChurnPredictor.Models;

namespace ChurnPredictor.Services;

public class ChurnModelService
{
    private readonly ILogger<ChurnModelService> _logger;
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;

    public MLContext MlContext => _mlContext;
    public ITransformer Model => _model;

    public ChurnModelService(ILogger<ChurnModelService> logger, string contentRootPath)
    {
        _logger = logger;
        _mlContext = new MLContext(seed: 42);

        var csvPath = Path.Combine(contentRootPath, "Data", "customers.csv");
        _logger.LogInformation("Loading data from {Path}", csvPath);

        var dataView = _mlContext.Data.LoadFromTextFile<CustomerData>(
            csvPath, hasHeader: true, separatorChar: ',');

        var split = _mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);

        var pipeline = _mlContext.Transforms.Conversion.MapValue(
                "Label",
                new[] {
                    new KeyValuePair<string, bool>("Yes", true),
                    new KeyValuePair<string, bool>("No", false)
                },
                inputColumnName: "Churned")
            .Append(_mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", "Region"))
            .Append(_mlContext.Transforms.Concatenate("Features", "Age", "Income", "RegionEncoded", "PurchaseHistory"))
            .Append(_mlContext.BinaryClassification.Trainers.FastTree());

        _logger.LogInformation("Training model...");
        _model = pipeline.Fit(split.TrainSet);

        var predictions = _model.Transform(split.TestSet);
        var metrics = _mlContext.BinaryClassification.Evaluate(predictions);

        _logger.LogInformation("Model Accuracy: {Accuracy:F4}", metrics.Accuracy);
        _logger.LogInformation("Model AUC: {Auc:F4}", metrics.AreaUnderRocCurve);
        _logger.LogInformation("Model F1: {F1:F4}", metrics.F1Score);
    }

    public ChurnPrediction Predict(CustomerData input)
    {
        var engine = _mlContext.Model.CreatePredictionEngine<CustomerData, ChurnPrediction>(_model);
        return engine.Predict(input);
    }
}

