using ChurnPredictor.Models;
using ChurnPredictor.Services;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

// Train model and save to disk at startup
var loggerFactory = LoggerFactory.Create(b => b.AddConsole());
var logger = loggerFactory.CreateLogger<ChurnModelService>();
var modelService = new ChurnModelService(logger, builder.Environment.ContentRootPath);

var modelPath = Path.Combine(builder.Environment.ContentRootPath, "churn_model.zip");
modelService.MlContext.Model.Save(modelService.Model, null, modelPath);
loggerFactory.Dispose();

builder.Services.AddSingleton(modelService);
builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromFile(filePath: modelPath, watchForChanges: false);

var app = builder.Build();

app.MapGet("/", () => "Hello");

app.MapPost("/predict", (PredictionEnginePool<CustomerData, ChurnPrediction> pool, CustomerPredictRequest request) =>
{
    var input = new CustomerData
    {
        Age = request.Age,
        Income = request.Income,
        Region = request.Region,
        PurchaseHistory = request.PurchaseHistory
    };

    var prediction = pool.Predict(input);

    return Results.Ok(new
    {
        willChurn = prediction.PredictedLabel,
        probability = prediction.Probability
    });
});

app.Run();

public record CustomerPredictRequest(float Age, float Income, string Region, float PurchaseHistory);

